package com.nexus.access.backend.auth; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import com.nexus.access.backend.user.UserResponseDTO;
/** Login and registration should be rate limited at the edge in production. */ @RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService service;public AuthController(AuthService s){service=s;}@PostMapping("/register") public ResponseEntity<UserResponseDTO> register(@Valid @RequestBody RegisterRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.register(r));}@PostMapping("/login") public LoginResponse login(@Valid @RequestBody LoginRequest r){return service.login(r);}@PostMapping("/refresh") public LoginResponse refresh(@Valid @RequestBody RefreshTokenRequest r){return service.refresh(r.refreshToken());}@PostMapping("/logout") @ResponseStatus(HttpStatus.NO_CONTENT) public void logout(@Valid @RequestBody LogoutRequest r){service.logout(r.refreshToken());}}
